    /// Mount ALL generated CRUD endpoints (12 per entity) with NO domain
    /// validation — the fully **unguarded** surface. A well-formed request can
    /// create invalid rows or soft-delete a referenced master out from under its
    /// dependents. Prefer a guarded composition (read + validated writes) for any
    /// real deployment; use this only in trusted/admin/seeding contexts.
    pub fn all_crud_routes(&self) -> Router {
        use presentation::http::{
            create_question_routes,
            create_question_answer_routes,
            create_survey_question_triggering_answer_routes,
            create_survey_routes,
            create_survey_survey_restrict_user_routes,
            create_survey_survey_lang_routes,
            create_user_input_read_routes,
            create_user_input_line_read_routes,
            create_survey_user_input_predefined_question_routes,
        };

        Router::new()
            .merge(create_question_routes(self.question_service.clone()))
            .merge(create_question_answer_routes(self.question_answer_service.clone()))
            .merge(create_survey_question_triggering_answer_routes(self.survey_question_triggering_answer_service.clone()))
            .merge(create_survey_routes(self.survey_service.clone()))
            .merge(create_survey_survey_restrict_user_routes(self.survey_survey_restrict_user_service.clone()))
            .merge(create_survey_survey_lang_routes(self.survey_survey_lang_service.clone()))
            .merge(create_user_input_read_routes(self.user_input_service.clone()))
            .merge(create_user_input_line_read_routes(self.user_input_line_service.clone()))
            .merge(create_survey_user_input_predefined_question_routes(self.survey_user_input_predefined_question_service.clone()))
    }

    /// Deprecated alias for [`Self::all_crud_routes`]. `routes()` reads like
    /// "the routes" but mounts UNVALIDATED generic CRUD on every entity — a naive
    /// mount exposes unguarded writes. Compose a guarded router (read + validated
    /// writes) for production, or call `all_crud_routes()` to opt into the full
    /// unguarded surface explicitly.
    #[deprecated(note = "mounts unvalidated generic CRUD; prefer readonly_routes() + validated writes, or all_crud_routes() for the full/unguarded surface")]
    pub fn routes(&self) -> Router {
        self.all_crud_routes()
    }

    /// Read-only routes for every entity (GET endpoints only) — the safe base.
    ///
    /// Generic mutation can't reach here, so this surface cannot bypass a
    /// validated write service's invariants. Use this as the production base and
    /// merge validated write routes (or a write service's HTTP layer) onto it.
    pub fn readonly_routes(&self) -> Router {
        use presentation::http::{
            create_question_read_routes,
            create_question_answer_read_routes,
            create_survey_question_triggering_answer_read_routes,
            create_survey_read_routes,
            create_survey_survey_restrict_user_read_routes,
            create_survey_survey_lang_read_routes,
            create_user_input_read_routes,
            create_user_input_line_read_routes,
            create_survey_user_input_predefined_question_read_routes,
        };

        Router::new()
            .merge(create_question_read_routes(self.question_service.clone()))
            .merge(create_question_answer_read_routes(self.question_answer_service.clone()))
            .merge(create_survey_question_triggering_answer_read_routes(self.survey_question_triggering_answer_service.clone()))
            .merge(create_survey_read_routes(self.survey_service.clone()))
            .merge(create_survey_survey_restrict_user_read_routes(self.survey_survey_restrict_user_service.clone()))
            .merge(create_survey_survey_lang_read_routes(self.survey_survey_lang_service.clone()))
            .merge(create_user_input_read_routes(self.user_input_service.clone()))
            .merge(create_user_input_line_read_routes(self.user_input_line_service.clone()))
            .merge(create_survey_user_input_predefined_question_read_routes(self.survey_user_input_predefined_question_service.clone()))
    }

    // <<< CUSTOM METHODS
    /// Compose the engagement badge-grant seam (deny-by-default until
    /// called — the PhoneBookPort shape): the ONE registered
